const response = $input.first().json;
const token = $('01 - Nuxeo Auth').first().json.token;
const lista = response.positions || response.targets || response || [];

if (!Array.isArray(lista) || lista.length === 0) {
  throw new Error('Nuxeo API não retornou nenhum veículo cadastrado.');
}

const now = new Date();
const past = new Date(now.getTime() - (24 * 60 * 60 * 1000)); // Últimas 24h
const pad = (n) => String(n).padStart(2, '0');
const fmtDate = (d) => `${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;

const begin = fmtDate(past);
const end = fmtDate(now);

const placasVistas = new Set();
const items = [];

for (const v of lista) {
  const placa = (v.identifier || '').trim().toUpperCase();
  if (!placa || placasVistas.has(placa)) continue;
  placasVistas.add(placa);
  items.push({
    json: {
      token,
      placa,
      begin,
      end,
      url: `https://api.nuxeo.com.br/rest/report/events/?begin=${encodeURIComponent(begin)}&end=${encodeURIComponent(end)}&plate=${placa}`
    }
  });
}

return items;

const rawItems = $input.all();

const esc = (v) => v != null ? String(v).replace(/'/g, "''") : null;
const valStr = (v) => v != null ? `'${esc(v)}'` : 'NULL';
const valNum = (v) => (v != null && !isNaN(v)) ? Number(v) : 'NULL';
const valJson = (obj) => `'${JSON.stringify(obj).replace(/'/g, "''")}'::jsonb`;

const sqlStatements = [];
sqlStatements.push(`
CREATE SCHEMA IF NOT EXISTS bronze;
CREATE TABLE IF NOT EXISTS bronze.nuxeo_eventos (
    id BIGSERIAL PRIMARY KEY,
    placa VARCHAR(20),
    complemento TEXT,
    nome_evento TEXT,
    data_evento TEXT,
    velocidade NUMERIC(6,2),
    latitude NUMERIC(10,6),
    longitude NUMERIC(10,6),
    endereco TEXT,
    cidade VARCHAR(150),
    estado VARCHAR(50),
    pais VARCHAR(50),
    payload_json JSONB,
    ingested_at TIMESTAMPTZ DEFAULT NOW()
);
`);

let totalRecords = 0;
for (const item of rawItems) {
  const resp = item.json;
  const events = resp.events || [];
  if (!Array.isArray(events) || events.length === 0) continue;

  const values = events.map(evt => {
    totalRecords++;
    return '('
      + valStr(evt.identifier || resp.placa) + ', '
      + valStr(evt.complement) + ', '
      + valStr(evt.event) + ', '
      + valStr(evt.date) + ', '
      + valNum(evt.speed) + ', '
      + valNum(evt.latitude) + ', '
      + valNum(evt.longitude) + ', '
      + valStr(evt.address) + ', '
      + valStr(evt.city) + ', '
      + valStr(evt.state) + ', '
      + valStr(evt.country) + ', '
      + valJson(evt)
      + ')';
  }).join(',\n');

  sqlStatements.push(`
    INSERT INTO bronze.nuxeo_eventos (
      placa, complemento, nome_evento, data_evento, velocidade, latitude, longitude, endereco, cidade, estado, pais, payload_json
    ) VALUES ${values};
  `);
}

if (totalRecords === 0) {
  return [{ json: { _sql: "SELECT 0 AS inseridos;", totalRecords: 0 } }];
}

return [{ json: { _sql: sqlStatements.join('\n'), totalRecords } }];
